import anthropic

try:
    resp = client.messages.create(...)
except anthropic.BadRequestError as e:
    print("请求本身有问题，别重试:", e.message)
except anthropic.RateLimitError as e:
    retry_after = int(e.response.headers.get("retry-after", "60"))
    print(f"被限流，{retry_after} 秒后再试")
except anthropic.APIStatusError as e:
    print("服务端错误" if e.status_code >= 500 else "其他 API 错误")

import time, random

def call_with_retry(fn, max_retries=5, base=1.0, cap=60.0):
    for n in range(max_retries):
        try:
            return fn()
        except anthropic.RateLimitError:
            pass                     # 429 可重试，进入退避
        except anthropic.APIStatusError as e:
            if e.status_code < 500:
                raise                # 终局错误，别重试
        delay = min(base * (2 ** n) + random.uniform(0, 1), cap)
        print(f"第 {n+1} 次重试，等待 {delay:.1f}s")
        time.sleep(delay)
    raise RuntimeError("重试耗尽")
